export type KathaRegistryPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function kathaRegistryProgram() {
  return <T extends KathaRegistryPluginRequirements>(
    client: T,
  ): ExtendedClient<T, { kathaRegistry: KathaRegistryPlugin }> => {
    return extendClient(client, {
      kathaRegistry: <KathaRegistryPlugin>{
        accounts: {
          artworkRecord: addSelfFetchFunctions(client, getArtworkRecordCodec()),
          artworkVerification: addSelfFetchFunctions(
            client,
            getArtworkVerificationCodec(),
          ),
          conditionAttestation: addSelfFetchFunctions(
            client,
            getConditionAttestationCodec(),
          ),
          conditionHead: addSelfFetchFunctions(client, getConditionHeadCodec()),
          custodyHead: addSelfFetchFunctions(client, getCustodyHeadCodec()),
          custodyTransition: addSelfFetchFunctions(client, getCustodyTransitionCodec()),
          kathaConfig: addSelfFetchFunctions(client, getKathaConfigCodec()),
          metadataHead: addSelfFetchFunctions(client, getMetadataHeadCodec()),
          metadataRevision: addSelfFetchFunctions(client, getMetadataRevisionCodec()),
          registryGovernance: addSelfFetchFunctions(
            client,
            getRegistryGovernanceCodec(),
          ),
          roleGrant: addSelfFetchFunctions(client, getRoleGrantCodec()),
        },
        instructions: {
          activateGovernance: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getActivateGovernanceInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          clearArtworkHold: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClearArtworkHoldInstructionAsync(input),
            ),
          createRoleGrant: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreateRoleGrantInstructionAsync({
                ...input,
                payer: input.payer ?? client.payer,
              }),
            ),
          initializeCondition: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeConditionInstructionAsync(input),
            ),
          initializeCustody: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeCustodyInstructionAsync(input),
            ),
          initializeMetadata: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeMetadataInstructionAsync(input),
            ),
          initializePlatform: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializePlatformInstructionAsync(input),
            ),
          mintArtwork: (input) =>
            addSelfPlanAndSendFunctions(client, getMintArtworkInstructionAsync(input)),
          placeArtworkHold: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPlaceArtworkHoldInstructionAsync(input),
            ),
          recordMintedCondition: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRecordMintedConditionInstructionAsync(input),
            ),
          recordUnmintedCondition: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRecordUnmintedConditionInstructionAsync(input),
            ),
          registerArtwork: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRegisterArtworkInstructionAsync(input),
            ),
          reviseMintedMetadata: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getReviseMintedMetadataInstructionAsync(input),
            ),
          reviseUnmintedMetadata: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getReviseUnmintedMetadataInstructionAsync(input),
            ),
          setGovernancePause: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetGovernancePauseInstructionAsync(input),
            ),
          transferMultisigAuthority: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getTransferMultisigAuthorityInstructionAsync(input),
            ),
          transitionCustody: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getTransitionCustodyInstructionAsync(input),
            ),
          updateRoleGrant: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateRoleGrantInstructionAsync(input),
            ),
          verifyArtwork: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getVerifyArtworkInstructionAsync(input),
            ),
        },
        pdas: {
          config: findConfigPda,
          governance: findGovernancePda,
          head: findHeadPda,
          grant: findGrantPda,
          verification: findVerificationPda,
          report: findReportPda,
          initializeCustodyHead: findInitializeCustodyHeadPda,
          transition: findTransitionPda,
          initializeMetadataHead: findInitializeMetadataHeadPda,
          revision: findRevisionPda,
          collectionAuthority: findCollectionAuthorityPda,
          asset: findAssetPda,
          artwork: findArtworkPda,
          reviseMintedMetadataRevision: findReviseMintedMetadataRevisionPda,
          transitionCustodyTransition: findTransitionCustodyTransitionPda,
        },
        identifyAccount: identifyKathaRegistryAccount,
        identifyInstruction: identifyKathaRegistryInstruction,
        parseInstruction: parseKathaRegistryInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
